🫛 snappea checks P models.

Usage: snappea [output options] <command> [options]

Commands:
  check      Find bugs in a model: run its test cases over many schedules.
             Use after every model change.
  replay     Re-run a bug's .schedule file to debug it or confirm a fix
  tests      List test cases, e.g. to pick one for `check`
  observe    Check logs of a real system against the model's spec monitors.
             Use to test that an implementation matches the model.
  coverage   Merge coverage from several runs (CI shards, processes)
  guide      How to model a design and test code against it. Start here:
             `snappea guide`, then `snappea guide testing` or `snappea guide syntax`.
  version    Print the version

Typical loop:
  snappea check                       # check every test case
  snappea replay PCheckerOutput/tcFoo/bug.schedule -v   # debug a bug
  snappea check tcFoo                 # confirm the fix

Commands that read P sources take .pproj or .p files. Without any, they use the
*.pproj file in the current folder, or else the *.p files in it and its immediate
subfolders.

Output is text on a terminal or in CI, JSON otherwise (agents, scripts).
--format text|json, --json or SNAPPEA_FORMAT=text|json override it.
--json-report FILE also writes the JSON result to FILE.

Run `snappea <command> --help` for a command's options and examples.

command:
mkdir -p /work && cd /work && cat > Lock.p <<'EOF'
/*
 * Lock service with fencing tokens. Store = two independent keys, each with atomic
 * load + CAS: the lock record (last token, holder, token, expiry) and the resource
 * record (highest accepted token). No cross-key atomicity.
 * LockContract = independent oracle from the task contract and the request history.
 * Client = load / decide / CAS-with-retry algorithm, generated ops and times.
 */
type Lease = (version: int, last: int, holder: int, token: int, expires: int);
type Res = (version: int, maxTok: int);
type Op = (kind: int, now: int, tok: int);

event eLoadLock: machine;
event eLockIs: Lease;
event eLoadRes: machine;
event eResIs: Res;
event eLockTry: (client: machine, cid: int, kind: int, now: int, tok: int, expected: int);
event eIssued: (client: machine, token: int);
event eIssuedIs: bool;
event eWriteTry: (client: machine, token: int, expected: int);
event eResult: int;
event eConflict;
event eClientDone;
event eDone;
event eAcq: (cid: int, now: int, token: int);
event eRel: (cid: int, token: int, now: int, ok: bool);
event eWrote: (token: int, ok: bool);

spec LockContract observes eAcq, eRel, eWrote, eDone {
  var last: int;
  var holder: int;
  var tok: int;
  var expires: int;
  var maxTok: int;
  var ops: int;
  start state Working {
    on eAcq do (p: (cid: int, now: int, token: int)) {
      ops = ops + 1;
      if (holder != 0 && p.now < expires) {
        if (holder == p.cid) { assert p.token == tok, "holder must get its own token back"; }
        else { assert p.token == 0, "lock held by another client must be refused"; }
      } else {
        assert p.token == last + 1, "tokens must strictly increase by issue";
        last = p.token; holder = p.cid; tok = p.token; expires = p.now + 2;
      }
    }
    on eRel do (p: (cid: int, token: int, now: int, ok: bool)) {
      var exp: bool;
      ops = ops + 1;
      exp = holder == p.cid && holder != 0 && tok == p.token && p.now < expires;
      assert p.ok == exp, "release result violates contract";
      if (exp) { holder = 0; }
    }
    on eWrote do (p: (token: int, ok: bool)) {
      var exp: bool;
      ops = ops + 1;
      exp = p.token >= 1 && p.token <= last && p.token >= maxTok;
      assert p.ok == exp, "fenced write result violates contract";
      if (exp) { maxTok = p.token; }
    }
    on eDone do { assert ops == 6, "driver must complete all operations"; }
  }
}

machine Store {
  var lk: Lease;
  var rs: Res;
  start state Ready {
    on eLoadLock do (c: machine) { send c, eLockIs, lk; }
    on eLoadRes do (c: machine) { send c, eResIs, rs; }
    on eLockTry do (p: (client: machine, cid: int, kind: int, now: int, tok: int, expected: int)) {
      var held: bool;
      held = lk.holder != 0 && p.now < lk.expires;
      if (p.expected != lk.version) { send p.client, eConflict; return; }
      if (p.kind == 0) {
        if (held) {
          if (lk.holder == p.cid) {
            announce eAcq, (cid = p.cid, now = p.now, token = lk.token);
            send p.client, eResult, lk.token;
          } else {
            announce eAcq, (cid = p.cid, now = p.now, token = 0);
            send p.client, eResult, 0;
          }
        } else {
          lk.last = lk.last + 1; lk.holder = p.cid; lk.token = lk.last;
          lk.expires = p.now + 2; lk.version = lk.version + 1;
          announce eAcq, (cid = p.cid, now = p.now, token = lk.token);
          send p.client, eResult, lk.token;
        }
      } else {
        if (held && lk.holder == p.cid && lk.token == p.tok) {
          lk.holder = 0; lk.version = lk.version + 1;
          announce eRel, (cid = p.cid, token = p.tok, now = p.now, ok = true);
          send p.client, eResult, 1;
        } else {
          announce eRel, (cid = p.cid, token = p.tok, now = p.now, ok = false);
          send p.client, eResult, 0;
        }
      }
    }
    on eIssued do (p: (client: machine, token: int)) {
      if (p.token < 1 || p.token > lk.last) { announce eWrote, (token = p.token, ok = false); }
      send p.client, eIssuedIs, (p.token >= 1 && p.token <= lk.last);
    }
    on eWriteTry do (p: (client: machine, token: int, expected: int)) {
      if (p.expected != rs.version) { send p.client, eConflict; return; }
      if (p.token < rs.maxTok) {
        announce eWrote, (token = p.token, ok = false); send p.client, eResult, 0;
      } else {
        rs.maxTok = p.token; rs.version = rs.version + 1;
        announce eWrote, (token = p.token, ok = true); send p.client, eResult, 1;
      }
    }
  }
}

machine Client {
  var store: Store;
  var coord: machine;
  var cid: int;
  start state Run {
    entry (input: (store: Store, coord: machine, cid: int, ops: seq[Op])) {
      var i: int;
      store = input.store; coord = input.coord; cid = input.cid;
      while (i < sizeof(input.ops)) {
        if (input.ops[i].kind == 2) { doWrite(input.ops[i].tok); }
        else { doLock(input.ops[i].kind, input.ops[i].now, input.ops[i].tok); }
        i = i + 1;
      }
      send coord, eClientDone;
    }
  }
  fun doLock(kind: int, now: int, tok: int) {
    var l: Lease;
    var done: bool;
    var attempts: int;
    while (!done) {
      attempts = attempts + 1;
      assert attempts <= 4, "bounded contention exceeded";
      send store, eLoadLock, this;
      receive { case eLockIs: (s: Lease) { l = s; } }
      send store, eLockTry, (client = this, cid = cid, kind = kind, now = now, tok = tok, expected = l.version);
      receive {
        case eResult: (r: int) { done = true; }
        case eConflict: { }
      }
    }
  }
  fun doWrite(token: int) {
    var r: Res;
    var done: bool;
    var ok: bool;
    var attempts: int;
    send store, eIssued, (client = this, token = token);
    receive { case eIssuedIs: (b: bool) { ok = b; } }
    if (!ok) { return; }
    while (!done) {
      attempts = attempts + 1;
      assert attempts <= 4, "bounded contention exceeded";
      send store, eLoadRes, this;
      receive { case eResIs: (s: Res) { r = s; } }
      send store, eWriteTry, (client = this, token = token, expected = r.version);
      receive {
        case eResult: (x: int) { done = true; }
        case eConflict: { }
      }
    }
  }
}

machine Scenario {
  var n: int;
  start state Running {
    entry (input: (a: seq[Op], b: seq[Op])) {
      var s: Store;
      s = new Store();
      new Client((store = s, coord = this, cid = 1, ops = input.a));
      new Client((store = s, coord = this, cid = 2, ops = input.b));
    }
    on eClientDone do { n = n + 1; if (n == 2) { announce eDone; } }
  }
}

fun mk(kind: int, now: int, tok: int): Op {
  return (kind = kind, now = now, tok = tok);
}

// Expiry boundary and takeover: A acquires at 0 (expires 2); B refused at 1, granted at 2;
// release at 1 vs token mismatch; stale token write after newer write.
machine Fixed {
  start state Init {
    entry {
      var a: seq[Op];
      var b: seq[Op];
      a += (0, mk(0, 0, 0)); a += (1, mk(1, 2, 1)); a += (2, mk(2, 0, 1));
      b += (0, mk(0, 1, 0)); b += (1, mk(0, 2, 0)); b += (2, mk(2, 0, 2));
      new Scenario((a = a, b = b));
    }
  }
}

// Generated: any op kind, times 0..3 (cross ttl=2 boundary), tokens 0..3.
machine Generated {
  start state Init {
    entry {
      var a: seq[Op];
      var b: seq[Op];
      var i: int;
      while (i < 3) {
        a += (i, mk(choose(3), choose(4), choose(4)));
        b += (i, mk(choose(3), choose(4), choose(4)));
        i = i + 1;
      }
      new Scenario((a = a, b = b));
    }
  }
}

test tcFixed [main=Fixed]: assert LockContract in { Fixed, Scenario, Client, Store };
test tcGenerated [main=Generated]: assert LockContract in { Generated, Scenario, Client, Store };
